<!doctype html><meta charset="utf-8"><body style="margin:0"><script>
'use strict';
// Minification microbench: identical drawImage conditions to scene.js drawPart.
const BG = 'rgb(16,24,52)';
function load(src) { return new Promise((ok, no) => { const i = new Image(); i.onload = () => ok(i); i.onerror = no; i.src = src; }); }
function canvas(w, h) { const c = document.createElement('canvas'); c.width = w; c.height = h; return c; }
function ctx2d(c, q) { const x = c.getContext('2d'); x.imageSmoothingEnabled = true; x.imageSmoothingQuality = q; return x; }

// CPU premultiplied area-average (box) resample of crop to integer tw x th.
function areaResample(img, crop, tw, th) {
  const [sx, sy, sx1, sy1] = crop, sw = sx1 - sx, sh = sy1 - sy;
  const c = canvas(sw, sh), x = c.getContext('2d', { willReadFrequently: true });
  x.drawImage(img, sx, sy, sw, sh, 0, 0, sw, sh);
  const d = x.getImageData(0, 0, sw, sh).data;
  const P = new Float64Array(sw * sh * 4);
  for (let i = 0; i < sw * sh; i++) {
    const a = d[i * 4 + 3] / 255;
    P[i * 4] = d[i * 4] * a; P[i * 4 + 1] = d[i * 4 + 1] * a; P[i * 4 + 2] = d[i * 4 + 2] * a; P[i * 4 + 3] = a;
  }
  const taps = (n, m) => { const k = n / m, out = []; for (let j = 0; j < m; j++) {
    const a = j * k, b = a + k, w = []; for (let i = Math.floor(a); i < Math.min(n, Math.ceil(b)); i++) {
      const v = Math.min(b, i + 1) - Math.max(a, i); if (v > 0) w.push([i, v / k]); } out.push(w); } return out; };
  const hx = taps(sw, tw), vy = taps(sh, th);
  const T = new Float64Array(tw * sh * 4);
  for (let y = 0; y < sh; y++) for (let j = 0; j < tw; j++) for (const [i, w] of hx[j])
    for (let ch = 0; ch < 4; ch++) T[(y * tw + j) * 4 + ch] += w * P[(y * sw + i) * 4 + ch];
  const out = new ImageData(tw, th), o = out.data;
  for (let j = 0; j < th; j++) for (let xx = 0; xx < tw; xx++) {
    let r = 0, g = 0, b = 0, a = 0;
    for (const [i, w] of vy[j]) { const k = (i * tw + xx) * 4; r += w * T[k]; g += w * T[k + 1]; b += w * T[k + 2]; a += w * T[k + 3]; }
    const q = (j * tw + xx) * 4;
    o[q + 3] = Math.round(a * 255);
    if (a > 0) { o[q] = Math.round(r / a); o[q + 1] = Math.round(g / a); o[q + 2] = Math.round(b / a); }
  }
  const res = canvas(tw, th); res.getContext('2d').putImageData(out, 0, 0);
  return res;
}
function halving(img, crop, tw, th) {
  let src = img, [sx, sy, sx1, sy1] = crop, sw = sx1 - sx, sh = sy1 - sy;
  while (sw / 2 >= tw && sh / 2 >= th) {
    const nw = Math.ceil(sw / 2), nh = Math.ceil(sh / 2), c = canvas(nw, nh);
    ctx2d(c, 'high').drawImage(src, sx, sy, sw, sh, 0, 0, nw, nh);
    src = c; sx = 0; sy = 0; sw = nw; sh = nh;
  }
  return { src, crop: [sx, sy, sx + sw, sy + sh] };
}
async function prepare(method, img, crop, r) {
  const tw = Math.max(1, Math.round(r.w)), th = Math.max(1, Math.round(r.h));
  if (method === 'bitmap_high') {
    const b = await createImageBitmap(img, crop[0], crop[1], crop[2] - crop[0], crop[3] - crop[1],
      { resizeWidth: tw, resizeHeight: th, resizeQuality: 'high', premultiplyAlpha: 'premultiply' });
    return { src: b, crop: [0, 0, tw, th] };
  }
  if (method === 'halving') return halving(img, crop, tw, th);
  if (method === 'area') return { src: areaResample(img, crop, tw, th), crop: [0, 0, tw, th] };
  if (method === 'area2x') return { src: areaResample(img, crop, 2 * tw, 2 * th), crop: [0, 0, 2 * tw, 2 * th] };
  return { src: img, crop };
}
async function run(cfg) {
  const out = {};
  const imgs = {};
  for (const [k, f] of Object.entries(cfg.sources)) imgs[k] = await load(f);
  for (const job of cfg.jobs) {
    const img = imgs[job.src], crop = job.crop, r = job.rect;
    const c = canvas(job.W, job.H), q = job.method.startsWith('direct_') ? job.method.slice(7) : 'high';
    const x = ctx2d(c, q);
    x.fillStyle = BG; x.fillRect(0, 0, job.W, job.H);
    const prep = await prepare(job.method, img, crop, r);
    const cc = prep.crop;
    if (job.method === 'via_tmp') {
      const t = canvas(job.W, job.H), tx = ctx2d(t, 'high');
      tx.drawImage(img, crop[0], crop[1], crop[2] - crop[0], crop[3] - crop[1], r.x, r.y, r.w, r.h);
      x.drawImage(t, 0, 0, job.W, job.H, 0, 0, job.W, job.H);
    } else {
      x.drawImage(prep.src, cc[0], cc[1], cc[2] - cc[0], cc[3] - cc[1], r.x, r.y, r.w, r.h);
    }
    out[job.id] = c.toDataURL('image/png');
  }
  return out;
}
window.Bench = { run };
</script>
